"use client";

import { useRef } from "react";
import { motion, useInView } from "framer-motion";
import { useLang } from "@/context/LangContext";

const portalIn = {
  hidden: { opacity: 0, scale: 0.72, rotateX: 28, y: 60, filter: "blur(16px)" },
  visible: (i: number) => ({
    opacity: 1, scale: 1, rotateX: 0, y: 0, filter: "blur(0px)",
    transition: { delay: i * 0.1, duration: 1.0, ease: [0.16, 1, 0.3, 1] },
  }),
};

const iconPop = {
  hidden: { scale: 0, rotate: -20 },
  visible: (i: number) => ({
    scale: 1, rotate: 0,
    transition: { delay: i * 0.1 + 0.2, duration: 0.5, type: "spring", bounce: 0.55 },
  }),
};

export default function Features() {
  const { t } = useLang();
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { once: true, margin: "-80px" });

  return (
    <section id="features" className="py-28 relative overflow-hidden" style={{ background: "#060d1b" }}>
      {/* Accent blobs */}
      <div className="absolute top-0 left-0 w-[400px] h-[400px] bg-primary/4 blur-3xl rounded-full pointer-events-none" />
      <div className="absolute bottom-0 right-0 w-[400px] h-[400px] bg-primary/4 blur-3xl rounded-full pointer-events-none" />

      <div className="max-w-6xl mx-auto px-6" ref={ref}>
        {/* Header */}
        <motion.div
          initial={{ opacity: 0, y: 40 }}
          animate={inView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}
          className="text-center mb-16"
        >
          <span className="inline-block glass border border-primary/30 text-primary text-xs font-bold uppercase tracking-widest px-4 py-2 rounded-full mb-5">
            {t.features.badge}
          </span>
          <h2 className="text-4xl lg:text-5xl font-black text-white mb-4">{t.features.title}</h2>
          <p className="text-white/50 text-lg max-w-lg mx-auto">{t.features.subtitle}</p>
        </motion.div>

        {/* Grid */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-5">
          {t.features.list.map((f, i) => (
            <motion.div
              key={i}
              custom={i}
              variants={portalIn}
              initial="hidden"
              animate={inView ? "visible" : "hidden"}
              style={{ perspective: "800px" }}
            >
              <div className="group h-full glass rounded-2xl p-6 border border-white/8 hover:border-primary/40 transition-all duration-300 cursor-default relative overflow-hidden">
                {/* Hover glow */}
                <div
                  className="absolute inset-0 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none"
                  style={{ background: "radial-gradient(circle at 30% 30%, rgba(13,148,136,0.12), transparent 70%)" }}
                />

                <div className="relative z-10">
                  {/* Icon with pop animation */}
                  <motion.div
                    custom={i}
                    variants={iconPop}
                    initial="hidden"
                    animate={inView ? "visible" : "hidden"}
                    className="w-12 h-12 rounded-xl bg-primary/10 border border-primary/20 flex items-center justify-center mb-4 text-2xl group-hover:bg-primary/20 group-hover:scale-110 transition-all duration-300"
                  >
                    {f.icon}
                  </motion.div>

                  <h3 className="text-lg font-bold text-white mb-2">{f.title}</h3>
                  <p className="text-white/50 text-sm leading-relaxed">{f.desc}</p>
                </div>

                {/* Bottom accent line */}
                <div className="absolute bottom-0 left-0 right-0 h-px bg-gradient-to-r from-transparent via-primary/30 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
