"use client";

import { useRef, useState, MouseEvent } from "react";
import { motion, useInView } from "framer-motion";
import { useLang } from "@/context/LangContext";

function ServiceCard({
  emoji, title, desc, price, delay, inView, index,
}: {
  emoji: string; title: string; desc: string; price: string;
  delay: number; inView: boolean; index: number;
}) {
  const cardRef = useRef<HTMLDivElement>(null);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });
  const [hovered, setHovered] = useState(false);

  const onMouseMove = (e: MouseEvent<HTMLDivElement>) => {
    const el = cardRef.current; if (!el) return;
    const { left, top, width, height } = el.getBoundingClientRect();
    setTilt({
      x: ((e.clientX - left) / width - 0.5) * 18,
      y: ((e.clientY - top) / height - 0.5) * -18,
    });
  };
  const onLeave = () => { setTilt({ x: 0, y: 0 }); setHovered(false); };

  // Alternating entrance: even from left, odd from right
  const fromX = index % 2 === 0 ? -80 : 80;

  return (
    <motion.div
      custom={delay}
      initial={{ opacity: 0, x: fromX, scale: 0.82, rotateX: 18, rotateY: index % 2 === 0 ? -12 : 12, filter: "blur(16px)" }}
      animate={inView ? {
        opacity: 1, x: 0, scale: 1, rotateX: 0, rotateY: 0, filter: "blur(0px)",
        transition: { delay, duration: 1.1, ease: [0.16, 1, 0.3, 1] },
      } : {}}
      style={{ perspective: "900px" }}
    >
      <div
        ref={cardRef}
        onMouseMove={onMouseMove}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={onLeave}
        style={{
          transform: `rotateX(${tilt.y}deg) rotateY(${tilt.x}deg)`,
          transition: hovered ? "transform 0.08s ease" : "transform 0.55s ease",
        }}
        className="shimmer glass h-full group relative rounded-2xl p-6 border border-white/8 hover:border-primary/40 transition-all duration-300 cursor-default overflow-hidden"
      >
        {/* Gradient border glow */}
        <div className="absolute inset-0 rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 pointer-events-none"
          style={{ background: "radial-gradient(circle at 50% 0%, rgba(13,148,136,0.18), transparent 65%)" }} />

        {/* Animated corner accent */}
        <div className="absolute top-0 right-0 w-20 h-20 rounded-bl-3xl opacity-0 group-hover:opacity-100 transition-all duration-500 pointer-events-none"
          style={{ background: "radial-gradient(circle at 100% 0%, rgba(13,148,136,0.15), transparent 70%)" }} />

        <div className="relative z-10">
          {/* Icon */}
          <div className="w-14 h-14 rounded-2xl flex items-center justify-center mb-5 text-3xl transition-all duration-300 group-hover:scale-110 group-hover:rotate-3"
            style={{ background: "linear-gradient(135deg, rgba(13,148,136,0.15), rgba(6,182,212,0.08))", border: "1px solid rgba(13,148,136,0.2)" }}>
            {emoji}
          </div>

          <h3 className="text-xl font-bold text-white mb-2">{title}</h3>
          <p className="text-white/50 text-sm leading-relaxed mb-5">{desc}</p>

          <div className="flex items-center justify-between">
            <span className="text-primary font-bold text-sm">{price}</span>
            <motion.div
              whileHover={{ scale: 1.15, rotate: 5 }}
              className="w-8 h-8 rounded-full border border-primary/30 flex items-center justify-center group-hover:bg-primary group-hover:border-primary transition-all duration-300">
              <span className="text-primary group-hover:text-white text-xs transition-colors">→</span>
            </motion.div>
          </div>
        </div>
      </div>
    </motion.div>
  );
}

export default function Services() {
  const { t } = useLang();
  const ref = useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { once: true, margin: "-80px" });

  return (
    <section id="services" className="py-28 relative overflow-hidden" style={{ background: "#060d1b" }}>
      <div className="absolute -bottom-40 right-0 w-[500px] h-[500px] bg-primary/5 blur-3xl rounded-full pointer-events-none" />
      <div className="absolute top-0 left-0 w-[300px] h-[300px] bg-cyan-500/3 blur-3xl rounded-full pointer-events-none" />

      <div className="max-w-6xl mx-auto px-6" ref={ref}>
        <motion.div initial={{ opacity: 0, y: 40 }} animate={inView ? { opacity: 1, y: 0 } : {}}
          transition={{ duration: 0.7 }} className="text-center mb-16">
          <span className="inline-block glass border border-primary/30 text-primary text-xs font-bold uppercase tracking-widest px-4 py-2 rounded-full mb-5">
            {t.services.badge}
          </span>
          <h2 className="text-4xl lg:text-5xl font-black text-white mb-4">{t.services.title}</h2>
          <p className="text-white/50 text-lg max-w-lg mx-auto">{t.services.subtitle}</p>
        </motion.div>

        <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-5">
          {t.services.list.map((s, i) => (
            <ServiceCard key={i} {...s} index={i} delay={i * 0.13} inView={inView} />
          ))}
        </div>
      </div>
    </section>
  );
}
